import { useCallback, useEffect, useRef, useState } from 'react'
import {
  ActivityIndicator,
  SafeAreaView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View
} from 'react-native'
import * as SecureStore from 'expo-secure-store'
import { ApiError, createApiClient, type SessionData, type TokenStore } from '@finvault/api-client'

type MobileUser = SessionData['user'] & {
  firstName?: string
}

type MobileSession = Omit<SessionData, 'user'> & {
  user: MobileUser
}

type NotificationList = {
  unreadCount: number
}

const refreshTokenKey = 'finvault.refreshToken'
const useMock = process.env.EXPO_PUBLIC_USE_MOCK === 'true'
const baseURL = process.env.EXPO_PUBLIC_API_BASE_URL ||
  `http://10.0.2.2:${useMock ? '4010' : '3000'}/api`

let accessToken: string | null = null
let refreshToken: string | null = null
let userId: string | null = null
let persistRefreshToken: Promise<void> = Promise.resolve()
let storageError: Error | null = null
let sessionExpiredHandler: (() => void) | undefined

const tokenStore: TokenStore = {
  getAccessToken: () => accessToken,
  getRefreshToken: () => refreshToken,
  getUserId: () => userId,
  setSession: (session) => {
    accessToken = session.accessToken
    refreshToken = session.refreshToken ?? null
    userId = session.user.id
    if (refreshToken) {
      storageError = null
      const currentRefreshToken = refreshToken
      persistRefreshToken = SecureStore.setItemAsync(refreshTokenKey, currentRefreshToken)
        .catch((error: unknown) => {
          storageError = error instanceof Error ? error : new Error('Không thể lưu phiên đăng nhập an toàn.')
        })
    }
  },
  clear: () => {
    accessToken = null
    refreshToken = null
    userId = null
    storageError = null
    persistRefreshToken = SecureStore.deleteItemAsync(refreshTokenKey)
      .catch((error: unknown) => {
        storageError = error instanceof Error ? error : new Error('Không thể xóa phiên đăng nhập an toàn.')
      })
  }
}

const api = createApiClient({
  baseURL,
  platform: 'mobile',
  tokenStore,
  onSessionExpired: () => sessionExpiredHandler?.()
})

function toVietnameseError(error: unknown): string {
  if (error instanceof ApiError) return error.message
  return 'Không thể kết nối máy chủ. Vui lòng thử lại.'
}

export default function App() {
  const [session, setSession] = useState<MobileSession | null>(null)
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [errorMessage, setErrorMessage] = useState('')
  const [unreadCount, setUnreadCount] = useState<number | null>(null)
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [retryRestore, setRetryRestore] = useState(false)
  const mountedRef = useRef(true)

  const restoreSession = useCallback(async () => {
    setLoading(true)
    setErrorMessage('')
    setRetryRestore(false)
    try {
      const storedRefreshToken = await SecureStore.getItemAsync(refreshTokenKey)
      if (!storedRefreshToken) return
      refreshToken = storedRefreshToken
      const restored = await api.auth.refresh<MobileSession>()
      await persistRefreshToken
      if (storageError) throw storageError
      if (mountedRef.current) setSession(restored)
    } catch (error) {
      const expired = error instanceof ApiError && error.code === 'SESSION_EXPIRED'
      if (expired) {
        tokenStore.clear()
        await persistRefreshToken
      }
      if (mountedRef.current) {
        setSession(null)
        setErrorMessage(expired
          ? 'Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.'
          : 'Không thể kết nối máy chủ. Vui lòng thử lại.')
        setRetryRestore(!expired)
      }
    } finally {
      if (mountedRef.current) setLoading(false)
    }
  }, [])

  useEffect(() => {
    mountedRef.current = true
    sessionExpiredHandler = () => {
      setSession(null)
      setErrorMessage('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.')
      setRetryRestore(false)
    }

    void restoreSession()
    return () => {
      mountedRef.current = false
      sessionExpiredHandler = undefined
    }
  }, [restoreSession])

  useEffect(() => {
    if (!session) {
      setUnreadCount(null)
      return
    }

    let active = true
    void api.notifications.list<NotificationList>()
      .then((result) => {
        if (active) setUnreadCount(result.unreadCount)
      })
      .catch((error: unknown) => {
        if (active) setErrorMessage(toVietnameseError(error))
      })

    return () => {
      active = false
    }
  }, [session])

  const signIn = async () => {
    setSubmitting(true)
    setErrorMessage('')
    setRetryRestore(false)
    try {
      const signedIn = await api.auth.signIn<MobileSession>({ username, password })
      await persistRefreshToken
      if (storageError) throw storageError
      setSession(signedIn)
      setPassword('')
    } catch (error) {
      const message = storageError?.message ?? toVietnameseError(error)
      if (storageError) {
        tokenStore.clear()
        await persistRefreshToken
      }
      setErrorMessage(message)
    } finally {
      setSubmitting(false)
    }
  }

  const signOut = async () => {
    setErrorMessage('')
    try {
      await api.auth.signOut()
      await persistRefreshToken
      if (storageError) throw storageError
      setSession(null)
    } catch (error) {
      await persistRefreshToken
      setErrorMessage(storageError?.message ?? toVietnameseError(error))
      setSession(null)
    }
  }

  if (loading) {
    return (
      <SafeAreaView style={styles.container}>
        <ActivityIndicator size="large" />
        <Text style={styles.muted}>Đang khôi phục phiên đăng nhập...</Text>
      </SafeAreaView>
    )
  }

  if (session) {
    return (
      <SafeAreaView style={styles.container}>
        <View style={styles.card}>
          <Text style={styles.title}>Xin chào {session.user.firstName || session.user.id}</Text>
          <Text style={styles.body}>
            Thông báo chưa đọc: {unreadCount === null ? 'Đang tải...' : unreadCount}
          </Text>
          {errorMessage ? <Text style={styles.error}>{errorMessage}</Text> : null}
          <TouchableOpacity style={styles.button} onPress={() => void signOut()}>
            <Text style={styles.buttonText}>Đăng xuất</Text>
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    )
  }

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.card}>
        <Text style={styles.title}>Đăng nhập FinVault</Text>
        <TextInput
          autoCapitalize="none"
          autoCorrect={false}
          onChangeText={setUsername}
          placeholder="Tên đăng nhập"
          style={styles.input}
          value={username}
        />
        <TextInput
          onChangeText={setPassword}
          placeholder="Mật khẩu"
          secureTextEntry
          style={styles.input}
          value={password}
        />
        {errorMessage ? <Text style={styles.error}>{errorMessage}</Text> : null}
        {retryRestore ? (
          <TouchableOpacity
            disabled={loading}
            onPress={() => void restoreSession()}
            style={[styles.button, loading && styles.disabled]}
          >
            <Text style={styles.buttonText}>{loading ? 'Đang thử lại...' : 'Thử lại'}</Text>
          </TouchableOpacity>
        ) : null}
        <TouchableOpacity
          disabled={submitting || !username || !password}
          onPress={() => void signIn()}
          style={[styles.button, (submitting || !username || !password) && styles.disabled]}
        >
          <Text style={styles.buttonText}>{submitting ? 'Đang đăng nhập...' : 'Đăng nhập'}</Text>
        </TouchableOpacity>
        <Text style={styles.muted}>{useMock ? 'Đang dùng mock API' : 'Kết nối Gateway'}</Text>
      </View>
    </SafeAreaView>
  )
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    backgroundColor: '#f4f7fb',
    flex: 1,
    justifyContent: 'center',
    padding: 24
  },
  card: {
    backgroundColor: '#ffffff',
    borderRadius: 16,
    gap: 16,
    maxWidth: 440,
    padding: 24,
    width: '100%'
  },
  title: {
    color: '#14243a',
    fontSize: 24,
    fontWeight: '700'
  },
  body: {
    color: '#334155',
    fontSize: 17
  },
  input: {
    borderColor: '#cbd5e1',
    borderRadius: 8,
    borderWidth: 1,
    fontSize: 16,
    padding: 12
  },
  button: {
    alignItems: 'center',
    backgroundColor: '#1456c0',
    borderRadius: 8,
    padding: 14
  },
  disabled: {
    opacity: 0.5
  },
  buttonText: {
    color: '#ffffff',
    fontSize: 16,
    fontWeight: '600'
  },
  error: {
    color: '#b42318'
  },
  muted: {
    color: '#64748b',
    textAlign: 'center'
  }
})

import { lazy, Suspense } from 'react'
import { createBrowserRouter, Navigate } from 'react-router-dom'
import { MainLayout } from '@/layouts/MainLayout'
import { AuthLayout } from '@/layouts/AuthLayout'
import { AdminLayout } from '@/layouts/AdminLayout'
import { RequireAuth, RequireRole, RedirectIfAuthed } from './guards'
import { Loader2 } from 'lucide-react'

// Lazy load các trang
const HomePage = lazy(() => import('@/pages/HomePage'))
const SignInPage = lazy(() => import('@/pages/SignInPage'))
const SignUpPage = lazy(() => import('@/pages/SignUpPage'))
const QrLoginPage = lazy(() => import('@/pages/QrLoginPage'))

const DashboardPage = lazy(() => import('@/pages/DashboardPage'))
const TransferPage = lazy(() => import('@/pages/TransferPage'))
const TopupPage = lazy(() => import('@/pages/TopupPage'))
const WithdrawPage = lazy(() => import('@/pages/WithdrawPage'))
const TransactionsPage = lazy(() => import('@/pages/TransactionsPage'))
const ProfilePage = lazy(() => import('@/pages/ProfilePage'))
const UtilitiesPage = lazy(() => import('@/pages/UtilitiesPage'))
const NotificationsPage = lazy(() => import('@/pages/NotificationsPage'))

const MerchantPortalPage = lazy(() => import('@/pages/MerchantPortalPage'))
const MerchantRegisterPage = lazy(() => import('@/pages/MerchantRegisterPage'))

const AdminDashboardPage = lazy(() => import('@/pages/AdminDashboardPage'))
const AdminKycPage = lazy(() => import('@/pages/AdminKycPage'))
const AdminReconciliationPage = lazy(() => import('@/pages/AdminReconciliationPage'))
const AdminTopupPage = lazy(() => import('@/pages/AdminTopupPage'))

const ForbiddenPage = lazy(() => import('@/pages/ForbiddenPage'))
const NotFoundPage = lazy(() => import('@/pages/NotFoundPage'))

function PageFallback() {
  return (
    <div className="flex h-64 w-full items-center justify-center" role="status">
      <Loader2 className="h-6 w-6 animate-spin text-primary" />
    </div>
  )
}

function withSuspense(Component: React.ComponentType) {
  return (
    <Suspense fallback={<PageFallback />}>
      <Component />
    </Suspense>
  )
}

export const router = createBrowserRouter([
  // 1. Công khai (Landing Page)
  {
    path: '/',
    element: (
      <RedirectIfAuthed>
        {withSuspense(HomePage)}
      </RedirectIfAuthed>
    )
  },

  // 2. Auth Routes (AuthLayout)
  {
    element: (
      <RedirectIfAuthed>
        <AuthLayout />
      </RedirectIfAuthed>
    ),
    children: [
      { path: 'sign-in', element: withSuspense(SignInPage) },
      { path: 'sign-up', element: withSuspense(SignUpPage) },
      { path: 'qr-login', element: withSuspense(QrLoginPage) }
    ]
  },

  // 3. Ứng dụng sau đăng nhập (MainLayout + RequireAuth)
  {
    path: 'app',
    element: (
      <RequireAuth>
        <MainLayout />
      </RequireAuth>
    ),
    children: [
      { index: true, element: withSuspense(DashboardPage) },
      { path: 'transfer', element: withSuspense(TransferPage) },
      { path: 'topup', element: withSuspense(TopupPage) },
      { path: 'withdraw', element: withSuspense(WithdrawPage) },
      { path: 'transactions', element: withSuspense(TransactionsPage) },
      { path: 'profile', element: withSuspense(ProfilePage) },
      { path: 'utilities', element: withSuspense(UtilitiesPage) },
      { path: 'notifications', element: withSuspense(NotificationsPage) }
    ]
  },

  // 4. Cổng Merchant (MainLayout + RequireAuth)
  {
    path: 'merchant',
    element: (
      <RequireAuth>
        <MainLayout />
      </RequireAuth>
    ),
    children: [
      { index: true, element: withSuspense(MerchantPortalPage) },
      { path: 'register', element: withSuspense(MerchantRegisterPage) }
    ]
  },

  // 5. Quản trị Admin (AdminLayout + RequireRole('ADMIN'))
  {
    path: 'admin',
    element: (
      <RequireAuth>
        <RequireRole role="ADMIN">
          <AdminLayout />
        </RequireRole>
      </RequireAuth>
    ),
    children: [
      { index: true, element: withSuspense(AdminDashboardPage) },
      { path: 'kyc', element: withSuspense(AdminKycPage) },
      { path: 'reconciliation', element: withSuspense(AdminReconciliationPage) },
      { path: 'topups', element: withSuspense(AdminTopupPage) }
    ]
  },

  // 6. Lỗi quyền và không tìm thấy trang
  {
    path: '403',
    element: withSuspense(ForbiddenPage)
  },
  {
    path: '404',
    element: withSuspense(NotFoundPage)
  },
  {
    path: '*',
    element: <Navigate to="/404" replace />
  }
])

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'

const badgeVariants = cva(
  'inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2',
  {
    variants: {
      variant: {
        default:
          'border-transparent bg-primary text-primary-foreground shadow hover:bg-primary/80',
        secondary:
          'border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80',
        destructive:
          'border-transparent bg-destructive text-destructive-foreground shadow hover:bg-destructive/80',
        outline: 'text-foreground',
        success: 'border-transparent bg-success text-success-foreground',
        warning: 'border-transparent bg-warning text-warning-foreground',
        info: 'border-transparent bg-info text-info-foreground'
      }
    },
    defaultVariants: {
      variant: 'default'
    }
  }
)

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  )
}

export { Badge, badgeVariants }

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'
import { Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-lg text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 cursor-pointer",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground shadow hover:bg-primary/90',
        destructive: 'bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90',
        outline: 'border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline'
      },
      size: {
        default: 'h-9 px-4 py-2',
        sm: 'h-8 rounded-md px-3 text-xs',
        lg: 'h-10 rounded-md px-6',
        icon: 'h-9 w-9'
      }
    },
    defaultVariants: {
      variant: 'default',
      size: 'default'
    }
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
  loading?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, loading = false, disabled, children, ...props }, ref) => {
    if (asChild) {
      return (
        <Slot
          className={cn(buttonVariants({ variant, size, className }))}
          ref={ref}
          {...props}
        >
          {children}
        </Slot>
      )
    }

    return (
      <button
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        disabled={disabled || loading}
        {...props}
      >
        {loading && <Loader2 className="animate-spin" aria-hidden="true" />}
        {children}
      </button>
    )
  }
)
Button.displayName = 'Button'

export { Button, buttonVariants }

