import api from '@/lib/axios'
import type { DashboardStats, AdminKycDocuments, AdminKycPage, AdminMerchantItem, AuditLogItem } from '../types/admin.types'
import type { KycStatus, UserProfile } from '@/features/user/types/user.types'
import { unwrap, type ApiResponse } from '@/lib/apiResponse'

const kycPath = (userId: string) => '/admin/kyc/' + encodeURIComponent(userId)

export const adminService = {
  /**
   * Thống kê Dashboard
   */
  getDashboardStats: async (): Promise<DashboardStats> => {
    const res = await api.get('/admin/dashboard')
    return res.data?.data ?? res.data
  },

  /**
   * Danh sách hồ sơ KYC
   */
  getKycList: async (params?: { page?: number; limit?: number; status?: KycStatus; search?: string }, signal?: AbortSignal): Promise<AdminKycPage> => {
    const res = await api.get<ApiResponse<AdminKycPage>>('/admin/kyc', { params, signal })
    return unwrap(res.data)
  },

  /**
   * Phê duyệt / Từ chối KYC
   */
  reviewKyc: async (userId: string, status: 'APPROVED' | 'REJECTED', detail: string): Promise<UserProfile> => {
    const res = await api.post<ApiResponse<UserProfile>>(kycPath(userId) + '/review', { status, detail: detail.trim() })
    return unwrap(res.data)
  },

  updateKycTier: async (userId: string, tier: 1 | 2, reason: string): Promise<UserProfile> => {
    const res = await api.patch<ApiResponse<UserProfile>>(kycPath(userId) + '/tier', { tier, reason: reason.trim() })
    return unwrap(res.data)
  },

  getKycDocuments: async (userId: string, signal?: AbortSignal): Promise<AdminKycDocuments> => {
    const res = await api.get<ApiResponse<AdminKycDocuments>>(kycPath(userId) + '/documents', { signal })
    return unwrap(res.data)
  },

  /**
   * Danh sách đối tác Merchant
   */
  getMerchantList: async (params?: { page?: number; limit?: number; status?: string; search?: string }): Promise<{ content: AdminMerchantItem[]; totalElements: number }> => {
    const res = await api.get('/admin/merchants', { params })
    return res.data?.data ?? res.data
  },

  /**
   * Phê duyệt / Từ chối Merchant
   */
  reviewMerchant: async (merchantId: string, status: 'APPROVED' | 'REJECTED', detail?: string): Promise<any> => {
    const res = await api.post(`/admin/merchants/${merchantId}/review`, { status, detail })
    return res.data?.data ?? res.data
  },

  /**
   * Lấy nhật ký kiểm toán Admin
   */
  getAuditLogs: async (params?: { page?: number; limit?: number }): Promise<AuditLogItem[]> => {
    const res = await api.get('/admin/audit-logs', { params })
    return res.data?.data ?? res.data
  }
}

import { useState, useRef, useEffect } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { ShieldCheck, Lock, AlertTriangle, Eye, EyeOff, Delete } from 'lucide-react'
import { formatVnd } from '@/lib/format'

export interface PinModalProps {
  open: boolean
  onOpenChange?: (open: boolean) => void
  title?: string
  description?: string
  paymentId?: string
  amount?: string
  onSuccess: (transactionToken: string) => void
  onCancel?: () => void
}

export function PinModal({
  open,
  onOpenChange,
  title = 'Xác thực mã PIN giao dịch',
  description = 'Vui lòng nhập mã PIN bảo mật 6 số để tiếp tục giao dịch.',
  amount,
  onSuccess,
  onCancel
}: PinModalProps) {
  const [pin, setPin] = useState<string[]>(Array(6).fill(''))
  const [showPin, setShowPin] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [errorMsg, setErrorMsg] = useState<string | null>(null)
  const [attemptsRemaining, setAttemptsRemaining] = useState(5)
  const [isLocked, setIsLocked] = useState(false)
  const [lockCountdown, setLockCountdown] = useState(300)

  const inputRefs = useRef<(HTMLInputElement | null)[]>([])

  // Reset trạng thái khi mở modal
  useEffect(() => {
    if (open) {
      setPin(Array(6).fill(''))
      setErrorMsg(null)
      setIsLoading(false)
      // Focus vào ô đầu tiên sau khi modal mở
      setTimeout(() => {
        inputRefs.current[0]?.focus()
      }, 100)
    }
  }, [open])

  // Đếm ngược khi bị khóa mã PIN (PIN_LOCKED)
  useEffect(() => {
    if (!isLocked) return

    if (lockCountdown <= 0) {
      setIsLocked(false)
      setAttemptsRemaining(5)
      setLockCountdown(300)
      setErrorMsg(null)
      return
    }

    const timer = setInterval(() => {
      setLockCountdown((prev) => prev - 1)
    }, 1000)

    return () => clearInterval(timer)
  }, [isLocked, lockCountdown])

  // Xử lý khi gõ ký tự vào từng ô
  const handleDigitChange = (index: number, value: string) => {
    if (isLocked || isLoading) return

    // Chỉ nhận ký tự số từ 0 đến 9
    const cleanValue = value.replace(/\D/g, '')
    if (!cleanValue) {
      const newPin = [...pin]
      newPin[index] = ''
      setPin(newPin)
      return
    }

    const lastDigit = cleanValue.slice(-1)
    const newPin = [...pin]
    newPin[index] = lastDigit
    setPin(newPin)
    setErrorMsg(null)

    // Tự động nhảy focus sang ô tiếp theo
    if (index < 5 && lastDigit) {
      inputRefs.current[index + 1]?.focus()
    }

    // Nếu đã nhập đủ 6 số -> Tự động xác thực
    const fullPin = newPin.join('')
    if (fullPin.length === 6 && !newPin.includes('')) {
      verifyPin(fullPin)
    }
  }

  // Xử lý phím Backspace điều hướng lùi
  const handleKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace' && !pin[index] && index > 0) {
      inputRefs.current[index - 1]?.focus()
    }
  }

  // Xử lý dán (Paste) mã 6 số từ clipboard
  const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
    e.preventDefault()
    if (isLocked || isLoading) return

    const pasteData = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, 6)
    if (!pasteData) return

    const newPin = Array(6).fill('')
    for (let i = 0; i < pasteData.length; i++) {
      newPin[i] = pasteData[i]
    }
    setPin(newPin)

    if (pasteData.length === 6) {
      verifyPin(pasteData)
    } else {
      inputRefs.current[pasteData.length]?.focus()
    }
  }

  // Xử lý bàn phím số ảo on-screen
  const handleVirtualKey = (key: string) => {
    if (isLocked || isLoading) return

    if (key === 'del') {
      const lastFilledIndex = pin.findLastIndex((d) => d !== '')
      if (lastFilledIndex >= 0) {
        const newPin = [...pin]
        newPin[lastFilledIndex] = ''
        setPin(newPin)
        inputRefs.current[lastFilledIndex]?.focus()
      }
      return
    }

    const firstEmptyIndex = pin.findIndex((d) => d === '')
    if (firstEmptyIndex !== -1) {
      handleDigitChange(firstEmptyIndex, key)
    }
  }

  // Hàm xác thực mã PIN
  const verifyPin = async (inputPin: string) => {
    setIsLoading(true)
    setErrorMsg(null)

    try {
      // Giả lập độ trễ xác thực bảo mật 400ms
      await new Promise((resolve) => setTimeout(resolve, 400))

      // Kịch bản demo: Mã PIN '000000' sẽ cố tình báo sai để kiểm thử trạng thái lỗi
      if (inputPin === '000000') {
        const newAttempts = attemptsRemaining - 1
        setAttemptsRemaining(newAttempts)

        if (newAttempts <= 0) {
          setIsLocked(true)
          setErrorMsg('Tài khoản bị tạm khóa giao dịch do nhập sai mã PIN quá 5 lần.')
        } else {
          setErrorMsg(`Mã PIN không chính xác. Bạn còn ${newAttempts} lần thử.`)
        }
        setPin(Array(6).fill(''))
        inputRefs.current[0]?.focus()
        return
      }

      // Nhập đúng mã PIN (hoặc các mã hợp lệ): sinh transactionToken dùng 1 lần
      const singleUseToken = 'txn_token_' + Math.random().toString(36).substring(2, 15)
      onSuccess(singleUseToken)
      onOpenChange?.(false)
    } finally {
      setIsLoading(false)
    }
  }

  // Format đếm ngược phút:giây
  const formatCountdown = (seconds: number) => {
    const mins = Math.floor(seconds / 60)
    const secs = seconds % 60
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`
  }

  const handleClose = () => {
    onCancel?.()
    onOpenChange?.(false)
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-md p-6 sm:p-8 bg-card border-border shadow-2xl rounded-2xl">
        <DialogHeader className="text-center space-y-2 sm:text-center">
          <div className="mx-auto h-12 w-12 rounded-2xl bg-primary/10 text-primary border border-primary/20 flex items-center justify-center shadow-sm">
            <Lock className="h-6 w-6" />
          </div>
          <DialogTitle className="text-xl font-bold tracking-tight text-foreground">
            {title}
          </DialogTitle>
          <DialogDescription className="text-xs text-muted-foreground">
            {description}
          </DialogDescription>
        </DialogHeader>

        {/* Thông tin số tiền giao dịch nếu có */}
        {amount && (
          <div className="p-3 rounded-xl bg-muted/40 border border-border/60 flex items-center justify-between text-xs">
            <span className="text-muted-foreground font-medium">Số tiền thanh toán:</span>
            <span className="font-extrabold text-primary text-base tracking-tight">
              {formatVnd(amount)}
            </span>
          </div>
        )}

        {/* Trạng thái bị khóa PIN_LOCKED */}
        {isLocked ? (
          <div className="p-4 rounded-xl bg-destructive/10 border border-destructive/20 text-center space-y-2">
            <div className="flex items-center justify-center gap-1.5 text-destructive font-semibold text-sm">
              <AlertTriangle className="h-4 w-4" />
              <span>Tài khoản tạm khóa giao dịch</span>
            </div>
            <p className="text-xs text-muted-foreground">
              Vui lòng thử lại sau: <strong className="text-foreground">{formatCountdown(lockCountdown)}</strong>
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {/* 6 Ô NHẬP MÃ PIN */}
            <div className="flex justify-center items-center gap-2 sm:gap-3 py-2">
              {pin.map((digit, index) => (
                <div key={index} className="relative">
                  <input
                    ref={(el) => {
                      inputRefs.current[index] = el
                    }}
                    type={showPin ? 'text' : 'password'}
                    inputMode="numeric"
                    maxLength={1}
                    value={digit}
                    disabled={isLocked || isLoading}
                    onChange={(e) => handleDigitChange(index, e.target.value)}
                    onKeyDown={(e) => handleKeyDown(index, e)}
                    onPaste={handlePaste}
                    className={`w-11 h-13 sm:w-12 sm:h-14 text-center text-xl font-bold rounded-xl border bg-surface-container-lowest text-foreground outline-none transition-all duration-150 ${
                      digit
                        ? 'border-primary ring-2 ring-primary/15'
                        : 'border-input focus:border-primary focus:ring-2 focus:ring-primary/20'
                    } ${errorMsg ? 'border-destructive ring-destructive/20' : ''}`}
                  />
                  {/* Hiệu ứng chấm tròn nếu đang che mật khẩu và có giá trị */}
                  {!showPin && digit && (
                    <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
                      <div className="h-3 w-3 rounded-full bg-primary" />
                    </div>
                  )}
                </div>
              ))}
            </div>

            {/* Nút bật/tắt hiển thị mã PIN */}
            <div className="flex items-center justify-between text-xs text-muted-foreground px-1">
              <div className="flex items-center gap-1">
                <ShieldCheck className="h-3.5 w-3.5 text-emerald-600" />
                <span>Mã hóa bảo mật 2 lớp</span>
              </div>
              <button
                type="button"
