                {errorMsg}
              </div>
            )}

            {/* BÀN PHÍM SỐ ẢO ON-SCREEN BẢO MẬT */}
            <div className="pt-2">
              <div className="grid grid-cols-3 gap-2 max-w-[280px] mx-auto">
