import { useEffect, useRef, useState } from 'react'
import { useForm, useWatch } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { toast } from 'sonner'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Button } from '@/components/ui/button'
import { errorCode, errorMessage } from '@/lib/apiResponse'
import { useAuthStore } from '@/features/auth/stores/useAuthStore'
import { kycSchema, MAX_KYC_FILE_SIZE, type KycFormValues } from '../schemas/user.schema'
import { userService } from '../services/userService'
import type { UserProfile } from '../types/user.types'
import { KycDocumentViewer } from './KycDocumentViewer'

export function KycForm({ profile, onSaved, onReload }: {
  profile: UserProfile; onSaved: (profile: UserProfile) => void; onReload: () => void
}) {
  const busy = useRef(false)
  const [needsReload, setNeedsReload] = useState(false)
  const { register, handleSubmit, control, setValue, setError, formState: { errors, isSubmitting } } = useForm<KycFormValues>({
    resolver: zodResolver(kycSchema), defaultValues: { idNumber: '' }
  })
  const front = useWatch({ control, name: 'front' })
  const back = useWatch({ control, name: 'back' })

  const submit = async (values: KycFormValues) => {
    if (busy.current || needsReload || !['NONE', 'REJECTED'].includes(profile.kycStatus)) return
    busy.current = true
    try {
      const saved = await userService.submitKyc(values)
      if (useAuthStore.getState().user?.id !== profile.authUserId) return
      onSaved(saved)
      toast.success('Đã gửi hồ sơ xác thực, vui lòng chờ xét duyệt.')
    } catch (reason) {
      if (useAuthStore.getState().user?.id !== profile.authUserId) return
      setError('root', { message: errorMessage(reason) })
      // Reload before retrying an upload whose outcome could be ambiguous.
      if (!['INVALID_IMAGE', 'INVALID_UPLOAD', 'KYC_DOCUMENT_REQUIRED', 'KYC_DOCUMENTS_REQUIRED', 'FILE_TOO_LARGE', 'VALIDATION_ERROR'].includes(errorCode(reason) ?? '')) {
        setNeedsReload(true)
      }
    } finally { busy.current = false }
  }
  const canSubmit = profile.kycStatus === 'NONE' || profile.kycStatus === 'REJECTED'
  return <div className="space-y-5">
    {profile.kycStatus === 'PENDING' && <p className="rounded-lg bg-amber-500/10 p-4 text-sm">Hồ sơ đang được xét duyệt. Bạn có thể tải lại trạng thái sau khi có kết quả.</p>}
    {profile.kycStatus === 'APPROVED' && <p className="rounded-lg bg-emerald-500/10 p-4 text-sm">Danh tính của bạn đã được xác thực.</p>}
    {profile.kycStatus === 'REJECTED' && <p className="rounded-lg bg-destructive/10 p-4 text-sm">Hồ sơ chưa được chấp thuận. Vui lòng kiểm tra thông tin và gửi lại ảnh giấy tờ rõ nét.</p>}
    {canSubmit && <form onSubmit={handleSubmit(submit)} className="space-y-4" noValidate>
      <div className="space-y-2">
        <Label htmlFor="kyc-number">Số CCCD / Passport</Label>
        <Input id="kyc-number" {...register('idNumber')} disabled={isSubmitting || needsReload}
          autoComplete="off" aria-invalid={!!errors.idNumber} aria-describedby="kyc-number-help" />
        <p id="kyc-number-help" className="text-xs text-muted-foreground">Nhập đúng số trên giấy tờ, tối đa 50 ký tự.</p>
        {errors.idNumber && <p role="alert" className="text-sm text-destructive">{errors.idNumber.message}</p>}
      </div>
      {(['front', 'back'] as const).map((side) => <div key={side} className="space-y-2">
        <Label htmlFor={`kyc-${side}`}>{side === 'front' ? 'Ảnh mặt trước' : 'Ảnh mặt sau'}</Label>
        <Input id={`kyc-${side}`} type="file" accept="image/jpeg,image/png" disabled={isSubmitting || needsReload}
          onChange={(event) => setValue(side, event.target.files?.[0] as File, { shouldValidate: true })}
          aria-invalid={!!errors[side]} aria-describedby={`kyc-${side}-help`} />
        <p id={`kyc-${side}-help`} className="text-xs text-muted-foreground">Ảnh JPEG hoặc PNG, tối đa 5 MiB. Chụp rõ thông tin và không che góc giấy tờ.</p>
        {errors[side] && <p role="alert" className="text-sm text-destructive">{errors[side].message}</p>}
        <ImagePreview file={side === 'front' ? front : back} label={side === 'front' ? 'mặt trước' : 'mặt sau'} />
      </div>)}
      {errors.root && <p role="alert" className="text-sm text-destructive">{errors.root.message}</p>}
      {needsReload
        ? <Button type="button" variant="outline" onClick={onReload}>Tải lại trạng thái hồ sơ</Button>
        : <Button type="submit" disabled={isSubmitting}>{isSubmitting ? 'Đang gửi hồ sơ…' : 'Gửi xác thực'}</Button>}
    </form>}
    {!canSubmit && <Button variant="outline" onClick={onReload}>Tải lại trạng thái</Button>}
    {profile.hasKycDocument && <KycDocumentViewer key={profile.updatedAt} authUserId={profile.authUserId} />}
  </div>
}

function ImagePreview({ file, label }: { file?: File; label: string }) {
  const [url, setUrl] = useState('')
  const [failed, setFailed] = useState(false)
  useEffect(() => {
    setFailed(false)
    if (!file || !['image/jpeg', 'image/png'].includes(file.type) || !file.size || file.size > MAX_KYC_FILE_SIZE) {
      setUrl(''); return
    }
    const next = URL.createObjectURL(file)
    setUrl(next)
    return () => URL.revokeObjectURL(next)
  }, [file])
  if (failed) return <p role="alert" className="text-sm text-destructive">Không đọc được ảnh {label}. Vui lòng chọn tệp khác.</p>
  return url ? <img src={url} alt={`Xem trước ${label}`} className="max-h-64 w-full rounded-lg border border-border object-contain" onError={() => setFailed(true)} /> : null
}

import { useRef } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { useAuthStore } from '@/features/auth/stores/useAuthStore'
import { errorMessage } from '@/lib/apiResponse'
import { buildProfileUpdate, createProfileSchema, profileDefaults, type ProfileFormValues } from '../schemas/user.schema'
import { userService } from '../services/userService'
import type { UserProfile } from '../types/user.types'

export function ProfileForm({ profile, onSaved }: { profile: UserProfile; onSaved: (profile: UserProfile) => void }) {
  const busy = useRef(false)
  const { register, handleSubmit, reset, setError, formState: { errors, isSubmitting, isDirty } } = useForm<ProfileFormValues>({
    resolver: zodResolver(createProfileSchema(profile)),
    defaultValues: profileDefaults(profile)
  })
  const submit = async (values: ProfileFormValues) => {
    if (busy.current) return
    const payload = buildProfileUpdate(profile, values)
    if (!Object.keys(payload).length) { toast.info('Không có thông tin thay đổi.'); return }
    busy.current = true
    try {
      const saved = await userService.updateProfile(profile.authUserId, payload)
      if (useAuthStore.getState().user?.id !== profile.authUserId) return
      reset(profileDefaults(saved))
      onSaved(saved)
      toast.success('Đã cập nhật hồ sơ')
    } catch (error) {
      if (useAuthStore.getState().user?.id === profile.authUserId) setError('root', { message: errorMessage(error) })
    } finally { busy.current = false }
  }
  return <form onSubmit={handleSubmit(submit)} className="space-y-5" noValidate>
    <div className="space-y-2">
      <Label htmlFor="profile-email">Email</Label>
      <Input id="profile-email" type="email" value={profile.email} readOnly aria-describedby="email-help" />
      <p id="email-help" className="text-xs text-muted-foreground">Email đăng nhập không thể thay đổi tại đây.</p>
    </div>
    {([
      ['fullName', 'Họ và tên', 'name'],
      ['phone', 'Số điện thoại', 'tel'],
      ['address', 'Địa chỉ', 'street-address']
    ] as const).map(([name, label, autoComplete]) => <div key={name} className="space-y-2">
      <Label htmlFor={'profile-' + name}>{label}</Label>
      <Input id={'profile-' + name} type={name === 'phone' ? 'tel' : 'text'} autoComplete={autoComplete}
        {...register(name)} disabled={isSubmitting} aria-invalid={!!errors[name]} aria-describedby={errors[name] ? name + '-error' : undefined} />
      {errors[name] && <p id={name + '-error'} role="alert" className="text-sm text-destructive">{errors[name]?.message}</p>}
    </div>)}
    {errors.root && <p role="alert" className="text-sm text-destructive">{errors.root.message}</p>}
    <Button type="submit" disabled={isSubmitting || !isDirty}>{isSubmitting ? 'Đang lưu…' : 'Lưu thông tin'}</Button>
  </form>
}

import { useEffect, useState } from 'react'
import { walletService } from '../services/walletService'
import type { WalletBalance } from '../types/wallet.types'
import { useAuthStore } from '@/features/auth/stores/useAuthStore'
import { TrendingUp, RefreshCw, AlertCircle, Eye, EyeOff } from 'lucide-react'

interface Props {
  className?: string
  refreshTrigger?: number
  onBalanceLoaded?: (balance: WalletBalance) => void
}

export const RealBalanceCard: React.FC<Props> = ({ className = '', refreshTrigger = 0, onBalanceLoaded }) => {
  const user = useAuthStore((state) => state.user)
  const [balance, setBalance] = useState<WalletBalance | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showBalance, setShowBalance] = useState(true)

  const fetchBalance = async () => {
    if (!user?.id) return
    try {
      setLoading(true)
      setError(null)
      const data = await walletService.getBalance(String(user.id))
      setBalance(data)
      onBalanceLoaded?.(data)
    } catch (err: any) {
      setError(err?.response?.data?.error?.message || 'Chưa khởi tạo ví hoặc lỗi kết nối')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchBalance()
  }, [user?.id, refreshTrigger])

  const formattedBalance = balance
    ? Number(balance.availableBalance || balance.balance || 0).toLocaleString('vi-VN')
    : '0'

  return (
    <div className={`rounded-2xl bg-linear-to-br from-violet-600 via-primary to-purple-800 p-6 text-white shadow-xl shadow-primary/20 flex flex-col justify-between ${className}`}>
      <div>
        <div className="flex items-center justify-between">
          <p className="text-xs font-semibold uppercase tracking-wider text-purple-200">
            Số dư khả dụng (Tiền thật)
          </p>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setShowBalance(!showBalance)}
              className="p-1 rounded-lg hover:bg-white/10 transition-colors text-purple-200"
              title={showBalance ? "Ẩn số dư" : "Hiện số dư"}
            >
              {showBalance ? <EyeOff className="size-3.5" /> : <Eye className="size-3.5" />}
            </button>
            <button
              onClick={fetchBalance}
              disabled={loading}
              className="p-1 rounded-lg hover:bg-white/10 transition-colors text-purple-200"
              title="Làm mới số dư"
            >
              <RefreshCw className={`size-3.5 ${loading ? 'animate-spin' : ''}`} />
            </button>
          </div>
        </div>

        {error ? (
          <div className="mt-2 flex items-center gap-1.5 text-xs text-rose-300">
            <AlertCircle className="size-3.5" />
            <span>{error}</span>
          </div>
        ) : loading && !balance ? (
          <div className="mt-2 h-10 w-48 bg-white/20 rounded-md animate-pulse"></div>
        ) : (
          <h2 className="text-2xl sm:text-4xl font-black tracking-tight mt-1">
            {showBalance ? `₫ ${formattedBalance}` : '•••••• VND'}
          </h2>
        )}
      </div>

      <div className="mt-6 flex items-center justify-between text-xs text-purple-200">
        <div className="flex items-center gap-2">
          <span className="inline-flex items-center gap-1 rounded-full bg-emerald-400/20 px-3 py-1 text-xs font-bold text-emerald-300 border border-emerald-400/30">
            <TrendingUp className="size-3" />
            VND
          </span>
          <span>{balance?.status === 'ACTIVE' ? 'Ví đang hoạt động' : 'Ví chưa kích hoạt'}</span>
        </div>
        {balance && Number(balance.heldBalance) > 0 && (
          <span className="text-amber-300">Đang giữ: ₫ {Number(balance.heldBalance).toLocaleString('vi-VN')}</span>
        )}
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { paymentService } from '@/features/payment/services/paymentService'
import { useAuthStore } from '@/features/auth/stores/useAuthStore'
import { X, PlusCircle, Loader2, ChevronUp, ChevronDown, CheckCircle2, Copy, AlertCircle, Timer } from 'lucide-react'
import { toast } from 'sonner'
import type { TopupResponse } from '@/features/payment/types/payment.types'

interface Props {
  isOpen: boolean
  onClose: () => void
  onSuccess?: () => void
}

const PRESET_AMOUNTS = [50000, 100000, 200000, 500000, 1000000]
const STEP = 50000

export const TopupModal: React.FC<Props> = ({ isOpen, onClose, onSuccess }) => {
  const user = useAuthStore((state) => state.user)
  const [amountDisplay, setAmountDisplay] = useState('100,000')
  const [amountValue, setAmountValue] = useState('100000')
  const [loading, setLoading] = useState(false)
  const [topupData, setTopupData] = useState<TopupResponse | null>(null)
  const [timeLeft, setTimeLeft] = useState(0)
  const [status, setStatus] = useState<'PENDING' | 'APPROVED' | 'EXPIRED' | 'REJECTED'>('PENDING')

  // Reset state when closed
  useEffect(() => {
    if (!isOpen) {
      setAmountDisplay('100,000')
      setAmountValue('100000')
      setTopupData(null)
      setStatus('PENDING')
      setTimeLeft(0)
    }
  }, [isOpen])

  // Polling for status
  useEffect(() => {
    if (!isOpen || !topupData || status !== 'PENDING') return

    const pollStatus = async () => {
      try {
        const res = await paymentService.getTopupStatus(topupData.topup.id)
        if (res.status === 'APPROVED') {
          setStatus('APPROVED')
          toast.success('Nạp tiền thành công!')
          onSuccess?.()
        } else if (res.status === 'REJECTED') {
          setStatus('REJECTED')
          toast.error('Yêu cầu nạp tiền đã bị từ chối')
        } else if (res.status === 'EXPIRED') {
          setStatus('EXPIRED')
        }
      } catch (error) {
        console.error('Lỗi khi kiểm tra trạng thái', error)
      }
    }

    const intervalId = setInterval(pollStatus, 5000)
    return () => clearInterval(intervalId)
  }, [isOpen, topupData, status, onSuccess])

  // Countdown timer
  useEffect(() => {
    if (!topupData || status !== 'PENDING') return

    const expiryTime = new Date(topupData.topup.expiresAt).getTime()

    const updateTimer = () => {
      const now = new Date().getTime()
      const diff = Math.floor((expiryTime - now) / 1000)

      if (diff <= 0) {
        setTimeLeft(0)
        setStatus('EXPIRED')
      } else {
        setTimeLeft(diff)
      }
    }

    updateTimer()
    const timerId = setInterval(updateTimer, 1000)

    return () => clearInterval(timerId)
  }, [topupData, status])

  if (!isOpen) return null

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/\D/g, '')
    setAmountValue(rawValue)
    setAmountDisplay(rawValue ? Number(rawValue).toLocaleString('vi-VN') : '')
  }

  const handlePresetSelect = (value: number) => {
    setAmountValue(value.toString())
    setAmountDisplay(value.toLocaleString('vi-VN'))
  }

  const handleStep = (direction: 'up' | 'down') => {
    let currentVal = Number(amountValue) || 0;
    if (direction === 'up') currentVal += STEP;
    else currentVal = Math.max(0, currentVal - STEP);

    setAmountValue(currentVal.toString());
    setAmountDisplay(currentVal ? currentVal.toLocaleString('vi-VN') : '0');
  }

  const handleCreateTopup = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!user?.id) {
      toast.error('Vui lòng đăng nhập để nạp tiền')
      return
    }
    if (!amountValue || Number(amountValue) < 10000) {
      toast.error('Số tiền nạp tối thiểu là 10,000 VND')
      return
    }

    try {
      setLoading(true)
      const res = await paymentService.createTopup(amountValue) as any
      if (res.paymentUrl) {
        window.location.href = res.paymentUrl
      } else {
        toast.error('Không nhận được đường dẫn thanh toán từ VNPAY')
        setLoading(false)
      }
    } catch (err: any) {
      toast.error('Tạo yêu cầu nạp tiền thất bại: ' + (err?.response?.data?.error?.message || err.message))
      setLoading(false)
    }
  }

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60).toString().padStart(2, '0')
    const s = (seconds % 60).toString().padStart(2, '0')
    return `${m}:${s}`
  }

  const handleCopy = (text: string, label: string) => {
    navigator.clipboard.writeText(text)
    toast.success(`Đã sao chép ${label}`)
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-xs p-4 overflow-y-auto">
      <div className="w-full max-w-md rounded-2xl bg-card border border-border p-6 shadow-2xl animate-in fade-in zoom-in-95 duration-200 my-8">
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-2 text-foreground font-bold text-lg">
            <PlusCircle className="size-5 text-primary" />
            <span>Nạp tiền vào ví</span>
          </div>
          <button onClick={onClose} className="rounded-lg p-1.5 hover:bg-muted text-muted-foreground transition-colors">
            <X className="size-4" />
          </button>
        </div>

        {/* STEP 1: INPUT AMOUNT */}
        {!topupData && (
          <form onSubmit={handleCreateTopup} className="space-y-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Số tiền nạp (VND)</label>
              <div className="relative">
                <input
                  type="text"
                  value={amountDisplay}
                  onChange={handleAmountChange}
                  className="w-full rounded-xl border border-input bg-background pl-4 pr-10 py-3 text-lg font-bold shadow-sm focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all"
                  placeholder="0"
                  required
                />
                <div className="absolute right-2 top-1/2 -translate-y-1/2 flex flex-col gap-0.5">
                  <button
                    type="button"
                    onClick={() => handleStep('up')}
                    className="p-1 bg-muted/80 hover:bg-muted text-muted-foreground rounded-t-sm transition-colors"
                  >
                    <ChevronUp className="size-3" />
                  </button>
                  <button
                    type="button"
                    onClick={() => handleStep('down')}
                    className="p-1 bg-muted/80 hover:bg-muted text-muted-foreground rounded-b-sm transition-colors"
                  >
                    <ChevronDown className="size-3" />
                  </button>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-2">
              {PRESET_AMOUNTS.map((val) => (
                <button
                  key={val}
                  type="button"
                  onClick={() => handlePresetSelect(val)}
                  className={`py-2 text-xs font-semibold rounded-lg border transition-all ${
                    amountValue === val.toString()
                      ? 'border-primary bg-primary/10 text-primary'
                      : 'border-border bg-muted/30 text-muted-foreground hover:bg-muted'
                  }`}
                >
                  {val.toLocaleString('vi-VN')}
                </button>
              ))}
            </div>

            <button
              type="submit"
              disabled={loading || !amountValue || Number(amountValue) < 10000}
              className="w-full rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed flex justify-center items-center gap-2 transition-all mt-4"
            >
              {loading && <Loader2 className="size-4 animate-spin" />}
              Tiếp tục
            </button>
          </form>
        )}

        {/* STEP 2 & 3: QR SCANNER & STATUS */}
        {topupData && status === 'PENDING' && (
          <div className="space-y-5">
            <div className="text-center space-y-1">
              <h3 className="font-semibold text-lg">Quét mã để thanh toán</h3>
              <p className="text-sm text-muted-foreground">Sử dụng App Ngân hàng hoặc Ví điện tử để quét mã</p>
