import api from '@/lib/axios'
import type { WalletBalance, WalletHistoryItem, WalletTransferResult } from '../types/wallet.types'
import { unwrap, type ApiResponse } from '@/lib/apiResponse'

export const walletService = {
  /**
   * Lấy số dư ví của người dùng
   */
  getBalance: async (userId: string): Promise<WalletBalance> => {
    const res = await api.get(`/wallets/${userId}/balance?ownerType=USER`)
    return res.data?.data ?? res.data
  },

  /**
   * Nạp tiền vào ví (Credit / Topup)
   */
  topup: async (userId: string, amount: string | number): Promise<any> => {
    const res = await api.post(`/wallets/${userId}/credit`, {
      amount: String(amount),
      referenceId: `TOPUP-${Date.now()}`,
      transferType: 'TOPUP'
    })
    return res.data?.data ?? res.data
  },

  /**
   * Trừ tiền ví (Debit)
   */
  debit: async (userId: string, amount: string | number, referenceId?: string): Promise<any> => {
    const res = await api.post(`/wallets/${userId}/debit`, {
      amount: String(amount),
      referenceId: referenceId || `DEBIT-${Date.now()}`,
      transferType: 'PAYMENT'
    })
    return res.data?.data ?? res.data
  },

  /**
   * Chuyển tiền P2P
   */
  transfer: async (userId: string, toUserId: string, amount: string, referenceId: string): Promise<WalletTransferResult> => {
    const res = await api.post<ApiResponse<WalletTransferResult>>(`/wallets/${encodeURIComponent(userId)}/transfer`, {
      toUserId,
      amount: String(amount),
      referenceId
    })
    const result = unwrap(res.data)
    if (!result || typeof result.transactionId !== 'string' || !result.transactionId) {
      throw new Error('Invalid transfer response')
    }
    return result
  },

  /**
   * Lịch sử biến động số dư
   */
  getHistory: async (userId: string, page = 1, limit = 10): Promise<WalletHistoryItem[]> => {
    const res = await api.get(`/wallets/${userId}/history`, {
      params: { page, limit }
    })
    return res.data?.data ?? res.data
  }
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

import { useCallback, useEffect, useRef, useState } from 'react'

type Resource<T> =
  | { key: string; status: 'loading'; data?: undefined; error?: undefined }
  | { key: string; status: 'success'; data: T; error?: undefined }
  | { key: string; status: 'error'; data?: undefined; error: unknown }

export function useRemoteResource<T>(key: string, load: (key: string, signal: AbortSignal) => Promise<T>) {
  const [revision, setRevision] = useState(0)
  const [state, setState] = useState<Resource<T>>({ key, status: 'loading' })
  const request = useRef(0)
  useEffect(() => {
    const controller = new AbortController()
    const version = ++request.current
    setState({ key, status: 'loading' })
    void load(key, controller.signal).then(
      (data) => {
        if (!controller.signal.aborted && request.current === version) setState({ key, status: 'success', data })
      },
      (error: unknown) => {
        if (!controller.signal.aborted && request.current === version) setState({ key, status: 'error', error })
      }
    )
    return () => { controller.abort(); request.current += 1 }
  }, [key, load, revision])
  const reload = useCallback(() => setRevision((value) => value + 1), [])
  const replace = useCallback((value: T | ((previous: T | undefined) => T)) => {
    request.current += 1
    setState((previous) => {
      const data = typeof value === 'function'
        ? (value as (previous: T | undefined) => T)(previous.key === key ? previous.data : undefined)
        : value
      return { key, status: 'success', data }
    })
  }, [key])
  const current: Resource<T> = state.key === key ? state : { key, status: 'loading' }
  return { ...current, reload, replace }
}

